def combinationSum(candidates, target):
    def backtrack(start, combo, remain):
        if remain == 0:
            result.append(list(combo))
            return
        for i in range(start, len(candidates)):
            if candidates[i] > remain:
                return  # prune
            combo.append(candidates[i])
            backtrack(i, combo, remain - candidates[i])  # same i: reuse
            combo.pop()

    candidates.sort()
    result = []
    backtrack(0, [], target)
    return result
